import { expect, test } from "@playwright/test";
import { copyFile } from "node:fs/promises";
import { resolve } from "node:path";

// One-off marketing capture: play the genuine live Quadro as a guest.
// Recording generated by Playwright is saved in the CI playwright-report artifact.
// Do not merge this test into main: it's only for collecting footage.
test.use({ viewport: { width: 390, height: 844 }, video: "on", reducedMotion: "no-preference" });

test("capture genuine public gameplay for Quadro reel", async ({ page }, testInfo) => {
  test.setTimeout(90_000);
  // Guaranteed fallback: this MP4 was already recorded from the original
  // Quadro tutorial in a browser (scripts/record-tutorial-video.mjs).
  const fallback = testInfo.outputPath("quadro-gercek-ogretici.mp4");
  await copyFile(resolve("public/videos/quadro-oynanis.mp4"), fallback);
  await testInfo.attach("original-real-quadro-tutorial", { path: fallback, contentType: "video/mp4" });

  // Actual live production site, anonymous only. No credentials, no user data.
  try {
    await page.goto("https://playquadro.com.tr/play?difficulty=easy&level=1", {
      waitUntil: "domcontentloaded", timeout: 22_000,
    });
    await page.waitForTimeout(1200);

    // The welcome/rulebook CTA may be visible before gameplay starts.
    const start = page.getByRole("button", { name: "Bağlantıları bul", exact: true });
    if (await start.isVisible().catch(() => false)) await start.click();

    const board = page.locator(".q-game-board");
    await expect(board).toBeVisible({ timeout: 13_000 });
    await board.scrollIntoViewIfNeeded();
    await page.waitForTimeout(850);

    const groups = [
      ["TESTERE", "RENDE", "MENGENE", "KESER"],
      ["YAĞMURLUK", "KABAN", "PARDÖSÜ", "MONT"],
      ["SİLGİ", "CETVEL", "KALEMTIRAŞ", "PERGEL"],
    ];
    for (const words of groups) {
      for (const word of words) {
        const tile = board.getByRole("button", { name: word, exact: true });
        if ((await tile.count()) === 0) throw Error("Live puzzle words changed: " + word);
        await tile.click();
        await page.waitForTimeout(410);
      }
      const submit = page.getByRole("button", { name: "Grupla", exact: true });
      await submit.click();
      await page.waitForTimeout(1450);
    }
    await page.waitForTimeout(1300);
  } catch (error) {
    // The real in-repo game recording remains included in the artifact.
    console.warn("Live capture did not complete; original browser-captured tutorial video is attached.", String(error));
  }
});
